import { useTranslation } from '@fanfanlo';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Dialog, DialogContent, DialogTitle, IconButton, List, ListItem, ListItemButton, ListItemText, Typography } from '@mui/material';
import type { IScript } from '../scripts/IScript';
import type { ScriptExamplesMap } from './ScriptExampleSelectorButton';

// 日志前缀
const LOG_PREFIX = '[ScriptExamplePopup]';

interface ScriptExamplePopupProps {
  open: boolean;
  onClose: () => void;
  examplesMap: ScriptExamplesMap | null;
  onSelectScript: (script: IScript) => void;
}

/**
 * 脚本示例选择弹窗组件
 * 显示分组的脚本示例列表
 */
export function ScriptExamplePopup({
  open,
  onClose,
  examplesMap,
  onSelectScript
}: ScriptExamplePopupProps) {
  console.log(`${LOG_PREFIX} 组件初始化, open: ${open}`);

  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');

  const handleClose = () => {
    console.log(`${LOG_PREFIX} 关闭按钮被点击`);
    onClose();
  };

  const handleSelectScript = (script: IScript) => {
    console.log(`${LOG_PREFIX} 选中脚本: ${script.name}, path: ${script.path}`);
    onSelectScript(script);
  };

  // 渲染分组
  const renderGroup = (level: 'beginner' | 'intermediate' | 'advanced') => {
    if (!examplesMap) {
      console.log(`${LOG_PREFIX} examplesMap 为空, 跳过渲染`);
      return null;
    }

    const scripts = examplesMap[level];
    console.log(`${LOG_PREFIX} 渲染分组: ${level}, 脚本数量: ${scripts.length}`);

    if (scripts.length === 0) {
      console.log(`${LOG_PREFIX} 分组 ${level} 没有脚本, 跳过渲染`);
      return null;
    }

    return (
      <Box key={level} sx={{ mb: 3 }}>
        <Typography variant="subtitle2" color="primary" sx={{ mb: 1, fontWeight: 'bold', px: 2 }}>
          {t(`ScriptExamplePopup.levels.${level}`)}
        </Typography>
        <List>
          {scripts.map((script) => {
            console.log(`${LOG_PREFIX} 渲染脚本项: ${script.name}`);
            return (
              <ListItem key={script.path} disablePadding>
                <ListItemButton onClick={() => handleSelectScript(script)}>
                  <ListItemText
                    primary={script.name}
                    secondary={script.desc}
                  />
                </ListItemButton>
              </ListItem>
            );
          })}
        </List>
      </Box>
    );
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      sx={{
        '& .MuiDialog-paper': {
          minHeight: '60vh',
          maxHeight: '80vh',
        },
      }}
    >
      <DialogTitle sx={{ m: 0, p: 2, pr: 6 }}>
        {t('ScriptExamplePopup.title')}
        <IconButton
          aria-label="close"
          onClick={handleClose}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: theme => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent dividers>
        {renderGroup('beginner')}
        {renderGroup('intermediate')}
        {renderGroup('advanced')}
      </DialogContent>
    </Dialog>
  );
}
